// Lê as linhas "⏳ ... desde dd/mm ..." do relatório publicado e fica com as abertas há 2+ dias úteis.
// Nunca cobra ex-colaboradores (mesma lista da trava de privacidade) nem o CEO. No máximo 5 por dia.
const EX_COLABORADORES = ['Redacted', 'Redacted', 'Redacted'];
const txt = String($input.first().json.resposta || '');
const hoje = $now.setZone('America/Sao_Paulo').startOf('day');
const diasUteis = d => { let n = 0, x = d.startOf('day'); while (x < hoje) { x = x.plus({ days: 1 }); if (x.weekday <= 5) n++; } return n; };
const out = [];
for (const raw of txt.split('\n')) {
  if (!raw.includes('⏳')) continue;
  const linha = raw.replace(/^[\s•*_]*⏳\s*/, '').trim();
  const d = linha.match(/desde\s+(\d{1,2})\/(\d{1,2})/i);
  if (!d) continue;
  let dt = DateTime.fromObject({ year: hoje.year, month: Number(d[2]), day: Number(d[1]) }, { zone: 'America/Sao_Paulo' });
  if (dt > hoje) dt = dt.minus({ years: 1 });
  const idade = diasUteis(dt);
  if (idade < 2) continue;
  if (EX_COLABORADORES.some(n => new RegExp('(^|[^\\wÀ-ÿ])' + n + '($|[^\\wÀ-ÿ])', 'i').test(linha))) continue;
  if (/Jos[ée] Redacted|\bCEO\b/i.test(linha)) continue;
  const espaco = ((linha.match(/\[([^,\]]+),/) || [])[1] || '').trim();
  const partes = linha.replace(/\[[^\]]*\]/g, '').split(/\s+[—-]\s+/).map(s => s.trim()).filter(Boolean);
  const pendencia = String(partes[0] || '').replace(/[.;*]+$/, '');
  const dono = String(partes.find((p, i) => i > 0 && !/desde|segue|aberta/i.test(p)) || '').replace(/[.;*]+$/, '');
  out.push({ json: { pendencia, desde: d[1].padStart(2, '0') + '/' + d[2].padStart(2, '0'), idade, espaco, dono } });
}
return out.slice(0, 5);

const itens = $input.all().map(i => i.json);
const linhas = itens.map((p, i) => (i + 1) + '. *' + p.pendencia + '* — aberta desde ' + p.desde + ' (' + p.idade + ' dias úteis)' + (p.dono ? ' — ' + p.dono : '') + '
   → vai para: ' + (p.espaco || 'REDACTED | Geral (espaço não identificado)'));
return [{ json: { texto: '🤖 *Zezinho — cobranças propostas* (' + itens.length + ')
Pendências do relatório abertas há 2+ dias úteis. Se aprovar, publico uma cobrança educada no espaço de cada uma:

' + linhas.join('
') } }];

// Acha o espaço pelo nome; sem nome conhecido, vai para o REDACTED | Geral.
// Saudação só com primeiros nomes de pessoas (tira setor: "Redacted / Comercial" → "Redacted").
const GERAL = 'spaces/<SPACE_ID>';
const SETORES = /^(comercial|cs|fiscal|cont[aá]bil|dp|rh|legaliza[cç][aã]o|societ[aá]rio|financeiro|operacional|equipe|setor|ti|marketing)$/i;
const lista = ($input.first().json.spaces || []);
const limpa = s => String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
return $('Pendências vencidas (sem IA)').all().map(i => {
  const p = i.json;
  const esp = lista.find(s => limpa(s.displayName) === limpa(p.espaco));
  const nomes = String(p.dono || '').split(/[\/,;&]|\se\s/).map(s => s.trim().split(/\s+/)[0]).filter(n => n && /^[A-ZÀ-Ý][a-zà-ÿ]+$/.test(n) && !SETORES.test(n));
  const quem = nomes.length ? 'Oi, ' + [...new Set(nomes)].join(' e ') + '! ' : 'Oi, pessoal! ';
  return { json: { space: esp ? esp.name : GERAL, text: '🤖 *Zezinho*\n' + quem + 'Passando para lembrar: *' + p.pendencia + '* está aberta desde ' + p.desde + '. Consegue atualizar aqui o andamento até amanhã? Se já resolveu, é só responder com ✅. Obrigado!' } };
});
